<script lang="ts">import {mailState,mailCommand} from '$lib/mail/store';import {dnsRecords} from '$lib/mail/model.js';export let domains:string[];let domain='',error='',notice='';$: {if(!domains.includes(domain))domain=domains[0]||'';}function verify(){try{mailCommand({type:'dns',domain});error='';notice='Example verification recorded. No network check was made.';}catch(e){error=e instanceof Error?e.message:'Verification failed.';}}async function copy(v:string){try{await navigator.clipboard.writeText(v);notice='Example record copied.';}catch{error='Clipboard unavailable.';}}</script>
{#if domain}<div class="stack"><div class="native-inline"><label class="field grow">Domain<select bind:value={domain}>{#each domains as d}<option>{d}</option>{/each}</select></label><button class="btn secondary" on:click={verify}>Simulate DNS check</button></div><div class="callout"><strong>{$mailState.dns[domain]?'Example verification passed':'Set up mail delivery'}</strong><p>Example records only. Your DNS provider remains authoritative. Review existing MX and SPF records; replacing them may interrupt mail.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}<section class="card table-card"><div class="table-head"><h3>Required DNS records</h3><p class="subtitle">Copy examples for review, not live use.</p></div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Name</th><th>Value</th><th></th></tr></thead><tbody>{#each dnsRecords(domain) as row}<tr><td>{row[0]}</td><td>{row[1]}</td><td class="mono native-path">{row[2]}</td><td><button class="btn secondary small" on:click={()=>copy(row[2])}>Copy</button></td></tr>{/each}</tbody></table></div></section><section class="card"><h3>Mail readiness</h3><div class="summary-list">{#each [['Incoming SMTP / port 25','Requires server and provider checks'],['Outbound SMTP / port 25','Not tested'],['Reverse DNS (PTR)','Set at your VPS provider'],['TLS certificates','Not installed'],['Spam filtering','Planned']] as row}<div><span>{row[0]}</span><strong>{row[1]}</strong></div>{/each}</div></section></div>{:else}<section class="card"><h3>No domains</h3><p class="subtitle">Add a domain before setting up mail.</p><a href="/domains" class="btn secondary">Add domain</a></section>{/if}
